using FormDesigner.DesignerSystem.AxamlRoundTrip;
using FormDesigner.Models;
using FormDesigner.Services;
using System.Reflection;
using System.Text.Json;
namespace FormDesigner.ExportSmokeTests;
internal static partial class Program
{
 private static int RunUniversal4DChecks()
 {
  int passed=0,failed=0;
  void Check(string name,Action test){try{test();passed++;Console.WriteLine("PASS PHASE4D_"+name);}catch(Exception e){failed++;Console.WriteLine("FAIL PHASE4D_"+name+": "+e);} }
  Check("CandidateOwnsMutableDTOs",()=>{var vm=Scene4C();var before=Text4C(vm);var dto=(DesignerDocumentFileModel)typeof(FormDesigner.ViewModels.MainWindowViewModel).GetMethod("AxamlCandidate",BindingFlags.NonPublic|BindingFlags.Instance)!.Invoke(vm,null)!;dto.Controls[0].Name="changed";dto.Controls[0].CustomProperties.Add(new(){Key="bad",ValueJson="true"});dto.Controls.RemoveAt(dto.Controls.Count-1);RequireCapability(Text4C(vm)==before&&!vm.Controls.Any(c=>c.Name=="changed"||c.CustomProperties.Any(p=>p.Key=="bad")),"Candidate aliases live model");});
  Check("OneSnapshotSerializationAfterWarmup",()=>{var vm=Scene4C();var host=Named4C(vm,"Host").Id;RequireCapability(vm.InsertAxamlControl("TextBlock",host,0,0)is not null,vm.StatusText);using var trace=LayoutDropProfile.Begin("4d","Insert");var n=vm.ActiveSession.UndoSnapshots.Count;RequireCapability(vm.InsertAxamlControl("Button",host,0,0)is not null,vm.StatusText);RequireCapability(trace.Stages.Single(s=>s.Stage=="CreateUndoSnapshot").Calls==1&&vm.ActiveSession.UndoSnapshots.Count==n+1,"Redundant snapshot or non-atomic entry");});
  Check("ScalarEditStillInHistory",()=>{var vm=Scene4C();var host=Named4C(vm,"Host").Id;RequireCapability(vm.InsertAxamlControl("Button",host,0,0)is not null,vm.StatusText);vm.SelectSingleControl(Named4C(vm,"First"));vm.CommitPropertyGridTextEdit(GetPropertyGridRow(vm,"Margin"),"7");vm.EndPropertyGridTextEdit();var scalar=Text4C(vm);RequireCapability(vm.InsertAxamlControl("TextBlock",host,0,0)is not null,vm.StatusText);GridEditorUndo(vm);RequireCapability(Text4C(vm)==scalar&&scalar.Contains("Margin=\"7\""),"Snapshot invalidation lost pending scalar");});
  Check("ExactAckReusesMapAndModels",()=>{var vm=Scene4C();vm.InsertAxamlControl("Button",Named4C(vm,"Host").Id,0,0);vm.MarkAxamlRoundTripSaved("warm.axaml",Text4C(vm),vm.ActiveSession.CurrentSnapshot);RequireCapability(vm.ReorderAxamlControl(Named4C(vm,"Second").Id,0),vm.StatusText);var map=vm.ActiveAxamlSourceDocument!.SourceMap;var controls=vm.Controls.ToArray();var text=Text4C(vm);using var trace=LayoutDropProfile.Begin("4d","Ack");vm.MarkAxamlRoundTripSaved("same.axaml",text,vm.ActiveSession.CurrentSnapshot);RequireCapability(ReferenceEquals(map,vm.ActiveAxamlSourceDocument!.SourceMap)&&controls.SequenceEqual(vm.Controls),"ACK replaced unchanged models/map");RequireCapability(trace.Stages.Any(s=>s.Stage=="AXAML.AcknowledgeReuse")&&!trace.Stages.Any(s=>s.Stage=="AXAML.StructuralSourceMapUpdate"),"ACK fully re-imported");RequireCapability(!vm.HasUnsavedChanges&&!vm.CreateActiveAxamlPatch(text).HasChanges,"ACK left phantom change");});
  Check("DelayedAckUsesSafeFallback",()=>{var vm=Scene4C();var grid=vm.InsertAxamlControl("Grid",Named4C(vm,"Host").Id,0,0)!;var text=Text4C(vm);var snapshot=vm.ActiveSession.CurrentSnapshot;var child=vm.InsertAxamlControl("TextBox",grid.Id,0,0)!;using var trace=LayoutDropProfile.Begin("4d","DelayedAck");vm.MarkAxamlRoundTripSaved("late.axaml",text,snapshot);RequireCapability(vm.HasUnsavedChanges&&Text4C(vm).Contains(child.Name)&&trace.Stages.Any(s=>s.Stage=="AXAML.StructuralSourceMapUpdate"),"Delayed ACK lost newer source state");GridEditorUndo(vm);RequireCapability(Text4C(vm)==text,"Undo after late ACK lost spans");});
  Check("InvalidAckDoesNotPublish",()=>{var vm=Scene4C();vm.InsertAxamlControl("Button",Named4C(vm,"Host").Id,0,0);var map=vm.ActiveAxamlSourceDocument;var snapshot=vm.ActiveSession.CurrentSnapshot;var text=Text4C(vm);try{vm.MarkAxamlRoundTripSaved("bad.axaml",text+"<!--bad-->",snapshot);throw new Exception("Invalid ACK accepted");}catch(InvalidOperationException){}RequireCapability(ReferenceEquals(map,vm.ActiveAxamlSourceDocument)&&Text4C(vm)==text&&vm.ActiveSession.CurrentSnapshot==snapshot,"Invalid ACK partially committed");});
  Check("ScalarSnapshotCannotAckOldProjection",()=>{var vm=Scene4C();vm.InsertAxamlControl("Button",Named4C(vm,"Host").Id,0,0);var old=vm.ActiveAxamlSourceDocument!.OriginalText;vm.SelectSingleControl(Named4C(vm,"First"));vm.CommitPropertyGridTextEdit(GetPropertyGridRow(vm,"Margin"),"9");vm.EndPropertyGridTextEdit();var before=Text4C(vm);try{vm.MarkAxamlRoundTripSaved("bad-scalar.axaml",old,vm.ActiveSession.CurrentSnapshot);throw new Exception("Old projection ACK accepted");}catch(InvalidOperationException){}RequireCapability(Text4C(vm)==before&&vm.HasUnsavedChanges,"Invalid scalar ACK partially saved");});
  Check("BusyRejectsReentrantStructure",()=>{var vm=Scene4C();var host=Named4C(vm,"Host").Id;bool attempted=false,rejected=false;vm.PropertyChanged+=(_,e)=>{if(e.PropertyName=="IsBusy"&&vm.IsBusy&&!attempted){attempted=true;rejected=vm.InsertAxamlControl("Button",host,0,0)is null;}};var count=vm.Controls.Count;RequireCapability(vm.InsertAxamlControl("TextBlock",host,0,0)is not null,vm.StatusText);RequireCapability(attempted&&rejected&&vm.Controls.Count==count+1&&!vm.IsBusy&&!vm.IsAxamlStructureBusy,"Reentrant command or stuck busy state");});
  Check("SourcePreviewDoesNotGenerateModelAxaml",()=>{var vm=Scene4C();var before=Text4C(vm);using var trace=LayoutDropProfile.Begin("4d","Preview");var p=vm.GenerateExportedAxamlPreviewSnapshot();RequireCapability(p.SourceKind=="ImportedAxaml"&&p.Axaml.Length==0&&p.GenerationFailure.Length==0&&p.Document.Controls.Count==vm.Controls.Count,"Imported Preview still regenerates model XML");using var preview=ShowDataGridRegressionPreview(vm,true);RequireCapability(Text4C(vm)==before,"Preview changed source");});
  foreach(var operation in new[]{"Insert","Remove","Reorder","Reparent"})Check("Large"+operation,()=>{var vm=GridFirstVm();try{vm.LoadAxamlImportedDocument(new AxamlImportService().Import(File.ReadAllText(Path.Combine(FindRepositoryRoot(),"Views","MainWindow.axaml"))));var before=Text4C(vm);var host=vm.ActiveAxamlSourceDocument!.SourceMap.Controls.First(r=>r.Element.LocalName is "Grid" or "StackPanel"&&vm.GetAxamlStructuralCapability(r.ControlId).CanAddChild);var c=vm.InsertAxamlControl("StackPanel",host.ControlId,0,0,index:int.MaxValue)!;var added=Text4C(vm);if(operation=="Insert"){GridEditorUndo(vm);RequireCapability(Text4C(vm)==before,"Large Insert Undo");}else{if(operation=="Remove")RequireCapability(vm.RemoveAxamlControls(new[]{c.Id}),vm.StatusText);if(operation=="Reorder")RequireCapability(vm.ReorderAxamlControl(c.Id,0),vm.StatusText);if(operation=="Reparent"){var child=vm.InsertAxamlControl("Button",c.Id,0,0)!;added=Text4C(vm);RequireCapability(vm.ReparentAxamlControl(child.Id,host.ControlId,0,0),vm.StatusText);}GridEditorUndo(vm);RequireCapability(Text4C(vm)==added,"Large operation Undo lost bytes");}GridEditorUndo(vm,true);RequireCapability(vm.CreateActiveAxamlPatch().CanApply,"Large Redo invalid");}finally{Dispose5AProfileVm(vm);}});
  Check("HundredOperationsAndSessionRelease",()=>{var vm=Scene4C();for(int i=0;i<50;i++){var c=vm.InsertAxamlControl("Button",Named4C(vm,"Host").Id,0,0)!;RequireCapability(vm.RemoveAxamlControls(new[]{c.Id}),vm.StatusText);if(i%10==0)vm.MarkAxamlRoundTripSaved("stress.axaml",Text4C(vm),vm.ActiveSession.CurrentSnapshot);}var text=Text4C(vm);RequireCapability(vm.Controls.Count==4&&!text.Contains("x:Name=\"Button1\""),"100 operations left detached control");vm.NewProjectEditorCommand!.Execute(null);RequireCapability(vm.ActiveAxamlSourceDocument is null,"Closed source session retained");});
  Console.WriteLine($"PHASE4D_CHECKS passed={passed}; failed={failed}");return failed==0?0:1;
 }
}
